    "source": "\"\"\"LCA by binary lifting. par[v-1] = parent of node v (1..n-1) and must satisfy par[v-1] < v; node 0 is the root. queries = flat pairs (u v).\"\"\"\n\n\ndef lca_all(par: list[int], queries: list[int]) -> list[int]:\n    n = len(par) + 1\n    log = 1\n    while (1 << log) < n:\n        log += 1\n    depth = [0] * n\n    for v in range(1, n):\n        depth[v] = depth[par[v - 1]] + 1\n    up = [[0] + par]\n    for j in range(1, log):\n        prev = up[j - 1]\n        up.append([prev[prev[v]] for v in range(n)])\n    out: list[int] = []\n    for q in range(0, len(queries) - 1, 2):\n        u, v = queries[q], queries[q + 1]\n        if depth[u] < depth[v]:\n            u, v = v, u\n        diff = depth[u] - depth[v]\n        for j in range(log):\n            if (diff >> j) & 1:\n                u = up[j][u]\n        if u != v:\n            for j in range(log - 1, -1, -1):\n                if up[j][u] != up[j][v]:\n                    u = up[j][u]\n                    v = up[j][v]\n            u = up[0][u]\n        out.append(u)\n    return out\n",
