    "source": "/** LCA by binary lifting. par[v-1] = parent of node v (1..n-1), must satisfy par[v-1] < v; node 0 is the root. queries = flat pairs (u v). */\npublic class Lca {\n    static long[] lcaAll(long[] par, long[] queries) {\n        int n = par.length + 1;\n        int LOG = 1;\n        while ((1 << LOG) < n) LOG++;\n        int[] depth = new int[n];\n        for (int v = 1; v < n; v++) depth[v] = depth[(int) par[v - 1]] + 1;\n        int[][] up = new int[LOG][n];\n        for (int v = 1; v < n; v++) up[0][v] = (int) par[v - 1];\n        for (int j = 1; j < LOG; j++)\n            for (int v = 0; v < n; v++) up[j][v] = up[j - 1][up[j - 1][v]];\n        long[] out = new long[queries.length / 2];\n        for (int q = 0; q + 1 < queries.length; q += 2) {\n            int u = (int) queries[q], v = (int) queries[q + 1];\n            if (depth[u] < depth[v]) { int t = u; u = v; v = t; }\n            int diff = depth[u] - depth[v];\n            for (int j = 0; j < LOG; j++) {\n                if (((diff >> j) & 1) == 1) u = up[j][u];\n            }\n            if (u != v) {\n                for (int j = LOG - 1; j >= 0; j--) {\n                    if (up[j][u] != up[j][v]) { u = up[j][u]; v = up[j][v]; }\n                }\n                u = up[0][u];\n            }\n            out[q / 2] = u;\n        }\n        return out;\n    }\n}\n",
