    "source": "// LCA by binary lifting. par[v-1] = parent of node v (1..n-1), must satisfy par[v-1] < v; node 0 is the root. queries = flat pairs (u v).\npub fn lca_all(par: &[i64], queries: &[i64]) -> Vec<i64> {\n    let n = par.len() + 1;\n    let mut log = 1usize;\n    while (1usize << log) < n { log += 1; }\n    let mut depth = vec![0usize; n];\n    for v in 1..n { depth[v] = depth[par[v - 1] as usize] + 1; }\n    let mut up = vec![vec![0usize; n]; log];\n    for v in 1..n { up[0][v] = par[v - 1] as usize; }\n    for j in 1..log { for v in 0..n { up[j][v] = up[j - 1][up[j - 1][v]]; } }\n    let mut out = Vec::new();\n    for q in queries.chunks_exact(2) {\n        let (mut u, mut v) = (q[0] as usize, q[1] as usize);\n        if depth[u] < depth[v] { std::mem::swap(&mut u, &mut v); }\n        let diff = depth[u] - depth[v];\n        for j in 0..log {\n            if (diff >> j) & 1 == 1 { u = up[j][u]; }\n        }\n        if u != v {\n            for j in (0..log).rev() {\n                if up[j][u] != up[j][v] { u = up[j][u]; v = up[j][v]; }\n            }\n            u = up[0][u];\n        }\n        out.push(u as i64);\n    }\n    out\n}\n",
