    "source": "package main\n\n// LCA by binary lifting. par[v-1] = parent of node v (1..n-1), must satisfy par[v-1] < v; node 0 is the root. queries = flat pairs (u v).\nfunc LcaAll(par []int64, queries []int64) []int64 {\n\tn := len(par) + 1\n\tlog := 1\n\tfor (1 << log) < n {\n\t\tlog++\n\t}\n\tdepth := make([]int, n)\n\tfor v := 1; v < n; v++ { depth[v] = depth[par[v-1]] + 1 }\n\tup := make([][]int, log)\n\tfor j := range up { up[j] = make([]int, n) }\n\tfor v := 1; v < n; v++ { up[0][v] = int(par[v-1]) }\n\tfor j := 1; j < log; j++ { for v := 0; v < n; v++ { up[j][v] = up[j-1][up[j-1][v]] } }\n\tout := []int64{}\n\tfor q := 0; q+1 < len(queries); q += 2 {\n\t\tu, v := int(queries[q]), int(queries[q+1])\n\t\tif depth[u] < depth[v] { u, v = v, u }\n\t\tdiff := depth[u] - depth[v]\n\t\tfor j := 0; j < log; j++ {\n\t\t\tif (diff>>j)&1 == 1 { u = up[j][u] }\n\t\t}\n\t\tif u != v {\n\t\t\tfor j := log - 1; j >= 0; j-- {\n\t\t\t\tif up[j][u] != up[j][v] { u = up[j][u]; v = up[j][v] }\n\t\t\t}\n\t\t\tu = up[0][u]\n\t\t}\n\t\tout = append(out, int64(u))\n\t}\n\treturn out\n}\n",
